  const ready=api('/api/stores').then(list=>{catalog=list;renderOptions()}).catch(()=>{catalogError='Не удалось получить список магазинов. Обновите страницу.'});
  function options(){return [{id:'',name:'Общий · все Ozon',market:'Ozon',color:'var(--chart-total, #315efb)'},...catalog.map((s,i)=>{const market=s.id.startsWith('wb-')?'WB':'Ozon',plain=market==='WB'?s.name.replace(/^WB\s*·\s*/i,''):s.name;return {id:s.id,name:market+' · '+plain,market,color:colors[i%colors.length]}})]}
