  function prefetchCategories(){const from=$('ins-from')?.value,to=$('ins-to')?.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to)return;void getCategoryDailyReport({from,to}).catch(()=>{})}
  function setMode(next){mode=next;$('chart-mode-stores').setAttribute('aria-pressed',String(mode==='stores'));$('chart-mode-categories').setAttribute('aria-pressed',String(mode==='categories'));$('chart-store-picker').hidden=mode!=='stores';$('chart-category-picker').hidden=true;if(mode==='categories'&&!report){$('chart-store-status').textContent='Загружаем категории…';prefetchCategories()}void render()}
