   const value=type=>typeValues.get(type.id),query=$('chart-category-table-search').value.trim().toLocaleLowerCase('ru-RU'),sortBy=$('chart-category-sort').value||'revenue';$('chart-category-level').disabled=Boolean(query);$('chart-category-collapse-all').disabled=Boolean(query);$('chart-category-search-note').hidden=!query;
   const compare=(left,right,currentOf,nameOf)=>{const a=currentOf(left),b=currentOf(right),knownA=sortBy==='revenue'?a.revenue!==null:sortBy==='units'?a.units!==null:a.observed,knownB=sortBy==='revenue'?b.revenue!==null:sortBy==='units'?b.units!==null:b.observed;if(knownA!==knownB)return knownA?-1:1;if(sortBy!=='name'){const key=sortBy==='units'?'units':'revenue',difference=(b[key]??0)-(a[key]??0);if(difference)return difference}return nameOf(left).localeCompare(nameOf(right),'ru')};
   const sorted=list=>[...list].sort((a,b)=>compare(a,b,value,item=>item.name));
