   const series=loaded.filter(r=>!r.forecastHistory).map(r=>r.report?{...r.store,report:r.report,points:PultStoreChart.points(r.report,key),total:PultStoreChart.totals(r.report,key),unavailable:r.store.market==='WB'&&(!['orderedRevenue','orderedUnits'].includes(key)||r.report.coverage?.orders!==true),errorMessage:r.report.error,warning:r.report.warning}:{...r.store,points:[],total:null,error:true});
   const forecastColors=['#ba9af2','#f3ad70','#80c6e8','#b9d982','#eab6cf'];
